CREATE OR REPLACE FUNCTION public.enforce_calculator_publish_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ok boolean;
  v_failures text[];
  v_role text;
  v_gate_sensitive_change boolean;
begin
  if new.publish_at is distinct from old.publish_at and auth.role() <> 'service_role' then
    select role into v_role from public.platform_admins where user_id = auth.uid() and active;
    if v_role not in ('owner','admin') or v_role is null then
      raise exception 'Owner or admin required to schedule publication';
    end if;
  end if;

  if new.lifecycle is distinct from old.lifecycle then
    if not (
      (old.lifecycle = 'draft' and new.lifecycle in ('review','archived')) or
      (old.lifecycle = 'review' and new.lifecycle in ('draft','certified','archived')) or
      (old.lifecycle = 'certified' and new.lifecycle in ('review','published','archived')) or
      (old.lifecycle = 'published' and new.lifecycle in ('review','archived')) or
      (old.lifecycle = 'archived' and new.lifecycle = 'draft')
    ) then
      raise exception 'Invalid lifecycle transition: % -> %', old.lifecycle, new.lifecycle;
    end if;

    if auth.role() <> 'service_role' then
      select role into v_role from public.platform_admins where user_id = auth.uid() and active;
      if v_role is null then raise exception 'Platform admin required'; end if;
      if v_role = 'editor' and new.lifecycle not in ('draft','review') then
        raise exception 'Editor cannot transition calculator to %', new.lifecycle;
      end if;
      if v_role = 'reviewer' and new.lifecycle = 'published' then
        raise exception 'Reviewer cannot publish calculators';
      end if;
    end if;
  end if;

  v_gate_sensitive_change :=
    new.lifecycle is distinct from old.lifecycle or
    new.risk_class is distinct from old.risk_class or
    new.source_count is distinct from old.source_count or
    new.reviewer_id is distinct from old.reviewer_id or
    new.metadata is distinct from old.metadata;

  if new.lifecycle in ('certified','published') and v_gate_sensitive_change then
    select ok, failures into v_ok, v_failures from public.validate_calculator_publish_gate(new.id);
    if not v_ok then raise exception 'Publishing gate failed: %', array_to_string(v_failures, '; '); end if;
  end if;

  if new.lifecycle = 'published' and new.published_at is null then new.published_at := now(); end if;
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_derived_source_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expected integer;
begin
  select count(*)::integer into v_expected
  from public.calculator_source_evidence
  where calculator_id = new.id;

  if auth.role() <> 'service_role' and new.source_count is distinct from v_expected then
    raise exception 'source_count is derived from calculator_source_evidence';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_qa_evidence_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
begin
  if auth.role() = 'service_role' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  select role into v_role
  from public.platform_admins
  where user_id = auth.uid() and active;

  if v_role not in ('owner','admin','reviewer') or v_role is null then
    raise exception 'Review-capable platform admin required';
  end if;

  if tg_op in ('INSERT','UPDATE') and new.status <> 'pending' then
    if new.checked_by is distinct from auth.uid() then
      raise exception 'QA evidence checked_by must match the authenticated reviewer';
    end if;
    if new.status = 'waived' and v_role not in ('owner','admin') then
      raise exception 'Owner or admin required to waive QA evidence';
    end if;
  end if;

  if tg_op = 'DELETE' and v_role not in ('owner','admin') then
    raise exception 'Owner or admin required to delete QA evidence';
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_qa_evidence_certification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_calculator_id uuid;
  v_lifecycle text;
  v_ok boolean;
  v_failures text[];
begin
  v_calculator_id := coalesce(new.calculator_id, old.calculator_id);
  select lifecycle into v_lifecycle from public.calculator_catalog_admin where id = v_calculator_id;

  if v_lifecycle in ('certified','published') then
    select ok, failures into v_ok, v_failures from public.validate_calculator_publish_gate(v_calculator_id);
    if not v_ok then
      raise exception 'Certified calculator evidence cannot become invalid: %', array_to_string(v_failures, '; ');
    end if;
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_reviewer_assignment_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_reviewer_valid boolean;
begin
  if tg_op = 'UPDATE' and new.reviewer_id is not distinct from old.reviewer_id then return new; end if;
  if tg_op = 'INSERT' and new.reviewer_id is null then return new; end if;
  if auth.role() <> 'service_role' then
    select role into v_role from public.platform_admins where user_id = auth.uid() and active;
    if v_role not in ('owner','admin') or v_role is null then
      raise exception 'Owner or admin required to assign calculator reviewer';
    end if;
  end if;
  if new.reviewer_id is not null then
    select exists(
      select 1 from public.platform_admins
      where user_id = new.reviewer_id and active and role in ('owner','admin','reviewer')
    ) into v_reviewer_valid;
    if not coalesce(v_reviewer_valid, false) then
      raise exception 'Reviewer must be an active review-capable admin';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_source_evidence_certification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_calculator_id uuid; v_lifecycle text; v_ok boolean; v_failures text[];
begin
  v_calculator_id := coalesce(new.calculator_id, old.calculator_id);
  select lifecycle into v_lifecycle from public.calculator_catalog_admin where id = v_calculator_id;
  if v_lifecycle in ('certified','published') then
    select ok, failures into v_ok, v_failures from public.validate_calculator_publish_gate(v_calculator_id);
    if not v_ok then
      raise exception 'Certified calculator source evidence cannot become invalid: %', array_to_string(v_failures, '; ');
    end if;
  end if;
  if tg_op = 'UPDATE' and new.calculator_id is distinct from old.calculator_id then
    select lifecycle into v_lifecycle from public.calculator_catalog_admin where id = old.calculator_id;
    if v_lifecycle in ('certified','published') then
      select ok, failures into v_ok, v_failures from public.validate_calculator_publish_gate(old.calculator_id);
      if not v_ok then
        raise exception 'Certified calculator source evidence cannot become invalid: %', array_to_string(v_failures, '; ');
      end if;
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_active_ymyl_reviewer_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.active and old.role in ('owner','admin','reviewer')
     and (not new.active or new.role not in ('owner','admin','reviewer')) then
    if exists(
      select 1 from public.calculator_catalog_admin c
      where c.reviewer_id = old.user_id
        and c.risk_class in ('financial','health','tax')
        and c.lifecycle in ('certified','published')
    ) then
      raise exception 'Reassign or decertify governed YMYL calculators before removing reviewer authority';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.stamp_source_evidence_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
  else
    new.created_at := old.created_at;
  end if;
  if auth.role() <> 'service_role' then
    new.reviewed_by := auth.uid();
    new.reviewed_at := now();
  elsif new.reviewed_at is null then
    new.reviewed_at := now();
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_source_evidence_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') then
    update public.calculator_catalog_admin
    set source_count = (select count(*)::integer from public.calculator_source_evidence where calculator_id = old.calculator_id)
    where id = old.calculator_id;
  end if;
  if tg_op in ('INSERT','UPDATE') and (tg_op = 'INSERT' or new.calculator_id is distinct from old.calculator_id) then
    update public.calculator_catalog_admin
    set source_count = (select count(*)::integer from public.calculator_source_evidence where calculator_id = new.calculator_id)
    where id = new.calculator_id;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_calculator_publish_gate(p_calculator_id uuid)
 RETURNS TABLE(ok boolean, failures text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_calc public.calculator_catalog_admin%rowtype;
  v_failures text[] := '{}';
  v_required text[] := array[
    'engine-tests','formula-review','sources','methodology',
    'reverse-solve','visualization-reconciliation','schedule-reconciliation',
    'scenario-reconciliation','sensitivity-validation','entitlement-validation',
    'ux-responsive','performance','security','seo-content','accessibility'
  ];
  v_check text; v_status text; v_rule jsonb; v_source jsonb; v_date text;
  v_reviewer_valid boolean; v_source_count integer;
begin
  if auth.role() <> 'service_role' and not public.is_platform_admin() then raise exception 'Platform admin required'; end if;
  select * into v_calc from public.calculator_catalog_admin where id = p_calculator_id;
  if v_calc.id is null then return query select false, array['Calculator not found']; return; end if;

  select count(*)::integer into v_source_count
  from public.calculator_source_evidence where calculator_id = p_calculator_id;
  if v_source_count < 1 then
    v_failures := array_append(v_failures, 'At least one reviewed source evidence record is required');
  end if;

  if lower(trim(coalesce(v_calc.metadata ->> 'rulePackRequired', ''))) = 'true' then
    v_required := array_append(v_required, 'rule-pack-validation');
    if coalesce(jsonb_typeof(v_calc.metadata -> 'ruleMetadata'), '') <> 'array'
       or coalesce(jsonb_array_length(v_calc.metadata -> 'ruleMetadata'), 0) = 0 then
      v_failures := array_append(v_failures, 'Complete regulatory rule metadata is required');
    else
      for v_rule in select value from jsonb_array_elements(v_calc.metadata -> 'ruleMetadata') loop
        if trim(coalesce(v_rule #>> '{jurisdiction,country}', '')) = ''
           or trim(coalesce(v_rule ->> 'ruleVersion', '')) = ''
           or coalesce(v_rule ->> 'effectiveFrom', '') !~ '^\\d{4}-\\d{2}-\\d{2}$'
           or coalesce(v_rule ->> 'lastVerifiedAt', '') !~ '^\\d{4}-\\d{2}-\\d{2}$'
           or coalesce(jsonb_typeof(v_rule -> 'officialSources'), '') <> 'array'
           or coalesce(jsonb_array_length(v_rule -> 'officialSources'), 0) = 0 then
          v_failures := array_append(v_failures, 'Regulatory rule metadata is incomplete'); exit;
        end if;
        foreach v_date in array array[v_rule ->> 'effectiveFrom', v_rule ->> 'lastVerifiedAt'] loop
          begin
            if to_char(v_date::date, 'YYYY-MM-DD') <> v_date then raise exception 'invalid date'; end if;
          exception when others then
            v_failures := array_append(v_failures, 'Regulatory rule metadata contains an invalid date'); exit;
          end;
        end loop;
        if array_position(v_failures, 'Regulatory rule metadata contains an invalid date') is not null then exit; end if;
        if v_rule ? 'effectiveTo' then
          v_date := v_rule ->> 'effectiveTo';
          begin
            if v_date !~ '^\\d{4}-\\d{2}-\\d{2}$'
               or to_char(v_date::date, 'YYYY-MM-DD') <> v_date
               or v_date::date < (v_rule ->> 'effectiveFrom')::date then raise exception 'invalid effective period'; end if;
          exception when others then
            v_failures := array_append(v_failures, 'Regulatory rule metadata contains an invalid effective period'); exit;
          end;
        end if;
        for v_source in select value from jsonb_array_elements(v_rule -> 'officialSources') loop
          if jsonb_typeof(v_source) <> 'object'
             or trim(coalesce(v_source ->> 'label', '')) = ''
             or trim(coalesce(v_source ->> 'url', '')) = '' then
            v_failures := array_append(v_failures, 'Regulatory official sources require labels and URLs'); exit;
          end if;
        end loop;
        if array_position(v_failures, 'Regulatory official sources require labels and URLs') is not null then exit; end if;
      end loop;
    end if;
  end if;

  if v_calc.risk_class in ('financial','health','tax') then
    v_required := array_append(v_required, 'ymyl-review');
    select exists(
      select 1 from public.platform_admins
      where user_id = v_calc.reviewer_id and active and role in ('owner','admin','reviewer')
    ) into v_reviewer_valid;
    if not coalesce(v_reviewer_valid, false) then
      v_failures := array_append(v_failures, 'Active review-capable YMYL reviewer is required');
    end if;
  end if;

  foreach v_check in array v_required loop
    select status into v_status from public.calculator_qa_checks
    where calculator_id = p_calculator_id and check_type = v_check;
    if coalesce(v_status, 'pending') not in ('passed','waived') then
      v_failures := array_append(v_failures, format('%s must pass', v_check));
    end if;
  end loop;
  return query select cardinality(v_failures) = 0, v_failures;
end;
$function$
